364:             Param(command,"@id",SqlDbType.BigInt,classId);
365:             int? capacity=null;
366:             await using(var reader=await command.ExecuteReaderAsync(ct)) {
367:                 if(!await reader.ReadAsync(ct)) errors.Add(new("ClassId","E-STU-010","指定クラスが存在しません。"));
