373:                     if(newSeat&&(!oldSeat||oldClass!=classId)&&(!reader.GetBoolean(4)||day<start||day>end)) errors.Add(new("ClassId","E-STU-013","このクラスには新たに所属できません。"));
374:                     if(status is "03" or "04"&&changedPeriod&&(student.Date("admission_date")>end||(DateOnly?)student.Values["enrollment_end_date"]<start)) errors.Add(new("ClassId","E-STU-108","在籍期間とクラス期間が重なりません。"));
375:                 }
376:             }
377:             if(newSeat&&(!oldSeat||oldClass!=classId)&&capacity is not null) {
378:                 await using var count=Command(connection,tx,"SELECT COUNT_BIG(*) FROM dbo.m_student WHERE class_id=@class AND is_deleted=0 AND enrollment_status_code IN ('01','02') AND (@id IS NULL OR student_id<>@id)");
379:                 Param(count,"@class",SqlDbType.BigInt,classId); Param(count,"@id",SqlDbType.BigInt,request.StudentId);
